import { For, Show, mergeProps } from "solid-js"

import type { orientationVariants } from "@/registry/kobalte/ui/orientation"
import type { ComboboxTriggerMode } from "@kobalte/core/combobox"
import type { VariantProps } from "class-variance-authority"
import type { Setter } from "solid-js"

import FormInputDescription from "@/registry/kobalte/form-inputs/form-input-description"
import FormInputErrors from "@/registry/kobalte/form-inputs/form-input-errors"
import CloseIcon from "@/registry/kobalte/icons/svg/close"
import { cn } from "@/registry/kobalte/lib/utils/tailwind"
import {
  ComboboxContent,
  ComboboxControl,
  ComboboxInput as ComboboxInputUI,
  ComboboxItem,
  ComboboxItemIndicator,
  ComboboxItemLabel,
  ComboboxSection,
  ComboboxTrigger,
  Combobox as ComboboxUI
} from "@/registry/kobalte/ui/combobox"
import { Label } from "@/registry/kobalte/ui/label"

export type ComboboxMultiInputProps<T> = {
  name: string
  value: Array<T> | undefined
  defaultValue?: Array<T>
  onChange: (value: Array<T> | null) => void | Setter<Array<T> | null>
  options: Array<T>
  optionValue: keyof T
  optionTextValue: keyof T
  optionLabel: keyof T
  optionDisabled: (option: T) => boolean
  optionDescriptionValue?: keyof T
  placeholder: string
  class?: string
  required?: boolean
  label?: string
  triggerLabel?: string
  description?: string
  error?: [string, ...Array<string>] | null
  disabled?: boolean
  readOnly?: boolean
  autofocus?: boolean
  defaultFilter?: "startsWith" | "endsWith" | "contains"
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean, triggerMode?: ComboboxTriggerMode) => void
  onInputChange?: (value: string) => void
  removeOnBackspace?: boolean
  allowDuplicateSelectionEvents?: boolean
  disallowEmptySelection?: boolean
  closeOnSelection?: boolean
  selectionBehavior?: "toggle" | "replace"
  virtualized?: boolean
  modal?: boolean
  preventScroll?: boolean
} & VariantProps<typeof orientationVariants>

const ComboboxMultiInput = <T,>(props: ComboboxMultiInputProps<T>) => {
  const comboProps = mergeProps(
    {
      optionValue: "" as keyof T,
      optionLabel: "" as keyof T,
      optionTextValue: "" as keyof T,
      optionDescriptionValue: "" as keyof T
    },
    props
  )
  const orientation = () => props.orientation ?? "vertical"
  return (
    <ComboboxUI<T>
      multiple={true}
      class={cn(
        "grid w-full items-center",
        orientation() === "horizontal" ? "gap-2 grid-cols-2 items-start" : "gap-1.5",
        props.error && "placeholder:text-destructive",
        props.class
      )}
      name={props.name}
      defaultFilter={props.defaultFilter}
      value={props.value}
      defaultValue={props.defaultValue}
      validationState={props.error ? "invalid" : "valid"}
      required={props.required}
      disabled={props.disabled}
      readOnly={props.readOnly}
      onChange={props.onChange}
      options={props.options}
      optionValue={comboProps.optionValue}
      optionTextValue={comboProps.optionTextValue}
      optionLabel={comboProps.optionLabel}
      optionDisabled={props.optionDisabled}
      placeholder={props.placeholder}
      open={props.open}
      defaultOpen={props.defaultOpen}
      removeOnBackspace={props.removeOnBackspace}
      allowDuplicateSelectionEvents={props.allowDuplicateSelectionEvents}
      disallowEmptySelection={props.disallowEmptySelection}
      closeOnSelection={props.closeOnSelection}
      selectionBehavior={props.selectionBehavior}
      virtualized={props.virtualized}
      modal={props.modal}
      preventScroll={props.preventScroll}
      itemComponent={(itemProps) => {
        const itemLabel = () => {
          return itemProps.item.rawValue?.[comboProps.optionTextValue] as unknown as
            string | number
        }
        const itemDesc = () => {
          const desc = itemProps.item.rawValue?.[
            comboProps.optionDescriptionValue
          ] as unknown as Array<string> | string | number
          if (Array.isArray(desc)) {
            return desc.join(", ")
          }
          if (typeof desc === "string") {
            return desc
          }
          if (typeof desc === "number") {
            return desc.toString()
          }
        }
        return (
          <ComboboxItem
            item={itemProps.item}
            class="flex items-center justify-between gap-2 wrap-break-word"
          >
            <div class="flex flex-col items-stretch wrap-break-word text-left">
              <ComboboxItemLabel>{itemLabel()}</ComboboxItemLabel>
              <Show when={itemDesc()}>
                <div class="max-w-xl text-sm text-muted-foreground">{itemDesc()}</div>
              </Show>
            </div>
            <ComboboxItemIndicator />
          </ComboboxItem>
        )
      }}
      sectionComponent={(sectionProps) => {
        const itemLabel = () => {
          return sectionProps.section.rawValue[
            comboProps.optionTextValue
          ] as unknown as string | number
        }
        return <ComboboxSection>{itemLabel()}</ComboboxSection>
      }}
    >
      <div class={cn("inline-flex flex-col gap-1.5")}>
        <Show when={props.label}>
          <Label class={cn("w-full", props.error ? "text-destructive" : "")}>
            {props.label} {props.required && <span class="text-destructive">*</span>}
          </Label>
        </Show>
        <FormInputDescription description={props.description} />
      </div>
      <ComboboxControl<T>
        aria-label={props.triggerLabel}
        class={cn("w-full min-h-10 h-auto", props.error ? "border-destructive" : "")}
      >
        {(state) => (
          <>
            <div class="flex w-full flex-col pr-2">
              <Show when={state.selectedOptions().length > 0}>
                <div class="flex shrink grow flex-wrap items-center gap-2 pt-1">
                  <For each={state.selectedOptions()}>
                    {(option) => {
                      const itemLabel = () => {
                        return option?.[comboProps.optionTextValue] as unknown as
                          string | number
                      }
                      return (
                        <span
                          class="inline-flex items-center gap-x-2 rounded bg-zinc-100 px-2 py-0.5 text-sm"
                          onPointerDown={(e) => e.stopPropagation()}
                        >
                          {itemLabel()}
                          <button
                            type="button"
                            onClick={(e) => {
                              e.stopPropagation()
                              state.remove(option)
                            }}
                            class="rounded-full p-0.5 hover:bg-zinc-200"
                          >
                            <CloseIcon class="size-4" />
                          </button>
                        </span>
                      )
                    }}
                  </For>
                </div>
              </Show>
              <ComboboxInputUI
                id={props.name}
                class={cn(
                  "py-2 min-h-9",
                  props.error && "placeholder:text-destructive"
                )}
              />
            </div>
            <button
              type="button"
              onPointerDown={(e) => e.stopPropagation()}
              onClick={(e) => {
                e.stopPropagation()
                state.clear()
              }}
              class={cn(
                "self-center rounded-full p-0.5 hover:bg-gray-200",
                props.error ? "text-destructive" : ""
              )}
            >
              <CloseIcon class="size-4" />
            </button>
            <ComboboxTrigger class={cn(props.error ? "text-destructive" : "")} />
          </>
        )}
      </ComboboxControl>
      <ComboboxContent class="max-h-60 overflow-y-auto" />
      <FormInputErrors
        class={cn(orientation() === "horizontal" ? "col-span-2" : "")}
        error={props.error}
      />
    </ComboboxUI>
  )
}

export default ComboboxMultiInput
